// Writes src/index.ts: Kevin's additions plus every shadcn component in src/components/ui, so components added
// by `shadcn add` (or the weekly sync) are importable by name without editing anything. Runs on every build.
import { readdirSync, writeFileSync } from 'node:fs'

const ui = readdirSync(new URL('../src/components/ui', import.meta.url))
    .filter((f) => f.endsWith('.tsx'))
    .map((f) => f.slice(0, -4))
    .sort()
writeFileSync(
    new URL('../src/index.ts', import.meta.url),
    [
        '// Generated by scripts/gen-index.mjs on every build; edit that script, not this file.',
        '',
        "// Kevin's additions: the byline, Data sources dialog, Stat and page helpers.",
        "export * from './byline'",
        "export { Byline } from './byline-react'",
        "export { DataSources, type DataSource } from './data-sources'",
        "export { Stat } from './stat'",
        '',
        '// Every shadcn component (base-nova style, zinc), customized where commented. Also importable one at a time from',
        "// '@kevinschaich/components/ui/<name>'.",
        ...ui.map((n) => `export * from './components/ui/${n}'`),
        '',
    ].join('\n'),
)
